// Generated from the guild's transcription of the server's forge and smelter
// menus — a one-time extraction, not a live feed, so a fresh transcription
// needs a re-run of scripts/gen_recipes.py.
//
// Everything came off one forge menu plus the smelter, so recipes are grouped
// by menu section rather than by which forge happens to carry them.

export interface RecipeIngredient {
  qty: number;
  item: string;
}

export interface Recipe {
  /** The crafting station this was recorded at. */
  station: string;
  category: string;
  name: string;
  /** Armour rating, or damage for weapons. 0 where the item has neither. */
  stat: number;
  ingredients: RecipeIngredient[];
}

export const RECIPE_NOTES: string[] = [
  "Transcribed from forge-menu footage covering A through Wrought Iron Shield. Anything alphabetically between Orcish Shield and Pokeblade — an Orcish Sword, War Axe or Warhammer, or Padded gear, if the server has them — fell between the two recordings and isn't listed.",
  "Smelter: the footage runs Corundum to Silver, so the Iron, Steel, Ebony, Orichalcum and Refined Moonstone ingot recipes weren't captured.",
  "A few readings were motion-blurred and are worth an in-game glance: Bipolar Blade's first material was too small to read and is missing; Nordic Carved Armor read as both 11 and 12 Steel Ingots (12 is listed); the Gold Ingot recipe's ore count read as 50; Rugged Plate Gauntlets and the Spellbinder Runic Boots and Gauntlets were caught mid-click, so their ratings are unknown; \"Dariit Arrow\" may be misspelled."
];

